## `modules/app-platform/variables.tf`

```hcl
# ---------------------------------------------------------------------------
# Identity / naming
# ---------------------------------------------------------------------------

variable "name_prefix" {
  description = "Prefix for all resource names, e.g. \"acme-web\"."
  type        = string

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{1,24}$", var.name_prefix))
    error_message = "name_prefix must be 2-25 chars, lowercase alphanumeric or hyphen, starting with a letter."
  }
}

variable "environment" {
  description = "Environment name. Drives all safety defaults."
  type        = string

  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be one of: dev, prod."
  }
}

variable "tags" {
  description = "Additional tags merged onto every taggable resource."
  type        = map(string)
  default     = {}
}

# ---------------------------------------------------------------------------
# Networking (assumed pre-existing; this module does not own the VPC)
# ---------------------------------------------------------------------------

variable "vpc_id" {
  description = "VPC in which the RDS instance and its security group live."
  type        = string
}

variable "database_subnet_ids" {
  description = "Private subnet IDs for the RDS subnet group. Must span >= 2 AZs."
  type        = list(string)

  validation {
    condition     = length(var.database_subnet_ids) >= 2
    error_message = "At least two subnets in distinct AZs are required for an RDS subnet group."
  }
}

variable "db_ingress_cidrs" {
  description = "CIDR blocks permitted to reach PostgreSQL on 5432 (e.g. node group CIDRs)."
  type        = list(string)
  default     = []

  validation {
    condition     = alltrue([for c in var.db_ingress_cidrs : can(cidrhost(c, 0))])
    error_message = "db_ingress_cidrs must contain valid CIDR blocks."
  }
}

variable "db_ingress_security_group_ids" {
  description = "Security group IDs permitted to reach PostgreSQL on 5432."
  type        = list(string)
  default     = []
}

# ---------------------------------------------------------------------------
# S3
# ---------------------------------------------------------------------------

variable "bucket_name" {
  description = "Explicit bucket name. If null, derived from name_prefix + environment + account id."
  type        = string
  default     = null
}

variable "enable_replication" {
  description = "Enable cross-region replication of the assets bucket."
  type        = bool
  default     = false
}

variable "replica_region" {
  description = "Destination region for cross-region replication."
  type        = string
  default     = "us-west-2"
}

variable "noncurrent_version_expiration_days" {
  description = "Days before noncurrent object versions are expired. 0 disables expiration."
  type        = number
  default     = 90

  validation {
    condition     = var.noncurrent_version_expiration_days >= 0
    error_message = "Must be >= 0."
  }
}

# ---------------------------------------------------------------------------
# RDS
# ---------------------------------------------------------------------------

variable "db_name" {
  description = "Initial database name."
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master username. Never \"postgres\" or \"admin\" (reserved)."
  type        = string
  default     = "appadmin"
}

variable "db_password" {
  description = <<-EOT
    Master password. Supplied from an encrypted source (SOPS-decrypted tfvars,
    AWS Secrets Manager data source, or TF_VAR_db_password from a vault agent).
    If null, a random 32-char password is generated and stored in Secrets Manager.
  EOT
  type        = string
  default     = null
  sensitive   = true
}

variable "db_instance_class" {
  description = "RDS instance class."
  type        = string
  default     = "db.t3.micro"
}

variable "db_engine_version" {
  description = "PostgreSQL major.minor version."
  type        = string
  default     = "16.3"
}

variable "db_allocated_storage" {
  description = "Initial storage in GiB."
  type        = number
  default     = 20
}

variable "db_max_allocated_storage" {
  description = "Upper bound for storage autoscaling in GiB. 0 disables autoscaling."
  type        = number
  default     = 100
}

variable "db_multi_az" {
  description = "Deploy a standby in a second AZ."
  type        = bool
  default     = false
}

variable "db_backup_retention_days" {
  description = "Automated backup retention in days. Spec floor is 7."
  type        = number
  default     = 7

  validation {
    condition     = var.db_backup_retention_days >= 7
    error_message = "Backup retention must be >= 7 days per platform policy."
  }
}

variable "db_backup_window" {
  description = "Daily backup window, UTC, format hh24:mi-hh24:mi."
  type        = string
  default     = "03:00-04:00"
}

variable "db_maintenance_window" {
  description = "Weekly maintenance window, ddd:hh24:mi-ddd:hh24:mi."
  type        = string
  default     = "sun:04:30-sun:05:30"
}

variable "db_performance_insights_enabled" {
  description = "Enable Performance Insights (not supported on t3.micro)."
  type        = bool
  default     = false
}

variable "db_apply_immediately" {
  description = "Apply modifications immediately instead of during maintenance window."
  type        = bool
  default     = false
}

# ---------------------------------------------------------------------------
# IAM
# ---------------------------------------------------------------------------

variable "oidc_provider_arn" {
  description = <<-EOT
    ARN of the cluster's IAM OIDC provider. When set, the service account role
    trusts the cluster via web identity federation (IRSA). Required for prod.
  EOT
  type        = string
  default     = null
}

variable "service_account_namespace" {
  description = "Kubernetes namespace of the service account allowed to assume the role."
  type        = string
  default     = "default"
}

variable "service_account_name" {
  description = "Kubernetes service account name allowed to assume the role."
  type        = string
  default     = "app"
}

variable "create_iam_user" {
  description = <<-EOT
    Create an IAM user with programmatic access for local/dev workflows.
    Policy forbids this in prod.
  EOT
  type        = bool
  default     = false
}

variable "bucket_prefixes_readwrite" {
  description = "Object key prefixes the role may read and write. Scopes s3:*Object grants."
  type        = list(string)
  default     = ["uploads/", "cache/"]
}

variable "bucket_prefixes_readonly" {
  description = "Object key prefixes the role may only read."
  type        = list(string)
  default     = ["public/"]
}
```

