## `modules/app-platform/locals.tf`

```hcl
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

locals {
  is_prod = var.environment == "prod"

  name = "${var.name_prefix}-${var.environment}"

  bucket_name = coalesce(
    var.bucket_name,
    "${local.name}-assets-${data.aws_caller_identity.current.account_id}"
  )

  replica_bucket_name = "${local.bucket_name}-replica"

  common_tags = merge(
    {
      Environment = var.environment
      Application = var.name_prefix
      ManagedBy   = "terraform"
      Module      = "app-platform"
    },
    var.tags
  )

  # ---------------------------------------------------------------------
  # Guardrails: fail fast at plan time rather than producing insecure infra.
  # ---------------------------------------------------------------------
  guardrails = {
    prod_requires_multi_az = (
      !local.is_prod || var.db_multi_az
    )
    prod_requires_oidc = (
      !local.is_prod || var.oidc_provider_arn != null
    )
    prod_forbids_iam_user = (
      !local.is_prod || !var.create_iam_user
    )
    prod_requires_replication = (
      !local.is_prod || var.enable_replication
    )
    replication_needs_region = (
      !var.enable_replication || var.replica_region != data.aws_region.current.name
    )
    ingress_source_required = (
      length(var.db_ingress_cidrs) + length(var.db_ingress_security_group_ids) > 0
    )
  }

  # Least privilege: prod uses per-prefix ARNs, never bucket-wide object wildcard.
  rw_object_arns = [
    for p in var.bucket_prefixes_readwrite :
    "${aws_s3_bucket.assets.arn}/${p}*"
  ]

  ro_object_arns = [
    for p in var.bucket_prefixes_readonly :
    "${aws_s3_bucket.assets.arn}/${p}*"
  ]

  allowed_list_prefixes = concat(
    var.bucket_prefixes_readwrite,
    var.bucket_prefixes_readonly,
    [for p in concat(var.bucket_prefixes_readwrite, var.bucket_prefixes_readonly) : "${p}*"]
  )
}

# Terraform has no top-level "assert"; check blocks give us plan-time failures
# with readable messages (Terraform >= 1.5).
check "environment_guardrails" {
  assert {
    condition     = local.guardrails.prod_requires_multi_az
    error_message = "prod must set db_multi_az = true."
  }
  assert {
    condition     = local.guardrails.prod_requires_oidc
    error_message = "prod must set oidc_provider_arn (IRSA trust); static keys are not permitted."
  }
  assert {
    condition     = local.guardrails.prod_forbids_iam_user
    error_message = "create_iam_user must be false in prod."
  }
  assert {
    condition     = local.guardrails.prod_requires_replication
    error_message = "prod must set enable_replication = true."
  }
  assert {
    condition     = local.guardrails.replication_needs_region
    error_message = "replica_region must differ from the primary region."
  }
  assert {
    condition     = local.guardrails.ingress_source_required
    error_message = "Provide at least one of db_ingress_cidrs or db_ingress_security_group_ids; the DB is not publicly accessible."
  }
}
```

