## `modules/app-platform/kms.tf`

```hcl
# ---------------------------------------------------------------------------
# Customer-managed key for RDS storage + Secrets Manager.
# dev uses AWS-managed keys (cheaper); prod uses a CMK with rotation.
# ---------------------------------------------------------------------------

resource "aws_kms_key" "data" {
  count = local.is_prod ? 1 : 0

  description             = "${local.name} data-at-rest key (RDS, Secrets Manager)"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key[0].json

  tags = merge(local.common_tags, { Name = "${local.name}-data" })
}

resource "aws_kms_alias" "data" {
  count = local.is_prod ? 1 : 0

  name          = "alias/${local.name}-data"
  target_key_id = aws_kms_key.data[0].key_id
}

data "aws_iam_policy_document" "kms_key" {
  count = local.is_prod ? 1 : 0

  statement {
    sid       = "AllowAccountRootAdministration"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowRDSAndSecretsManagerUse"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]

    resources = ["*"]

    principals {
      type = "Service"
      identifiers = [
        "rds.amazonaws.com",
        "secretsmanager.amazonaws.com",
      ]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

locals {
  # null => AWS-managed key (aws/rds, aws/secretsmanager)
  data_kms_key_arn = local.is_prod ? aws_kms_key.data[0].arn : null
}
```

