## `modules/app-platform/rds.tf`

```hcl
resource "random_password" "db" {
  count = var.db_password == null ? 1 : 0

  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_upper        = 2
  min_lower        = 2
  min_numeric      = 2
  min_special      = 2
}

locals {
  db_password_effective = coalesce(var.db_password, try(random_password.db[0].result, null))
}

# ---------------------------------------------------------------------------
# Network placement
# ---------------------------------------------------------------------------

resource "aws_db_subnet_group" "main" {
  name        = "${local.name}-db"
  description = "Private subnets for ${local.name} PostgreSQL"
  subnet_ids  = var.database_subnet_ids

  tags = merge(local.common_tags, { Name = "${local.name}-db" })
}

resource "aws_security_group" "db" {
  name        = "${local.name}-db"
  description = "PostgreSQL ingress for ${local.name}"
  vpc_id      = var.vpc_id

  tags = merge(local.common_tags, { Name = "${local.name}-db" })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_vpc_security_group_ingress_rule" "db_from_cidr" {
  for_each = toset(var.db_ingress_cidrs)

  security_group_id = aws_security_group.db.id
  description       = "PostgreSQL from ${each.value}"
  cidr_ipv4         = each.value
  from_port         = 5432
  to_port           = 5432
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_ingress_rule" "db_from_sg" {
  for_each = toset(var.db_ingress_security_group_ids)

  security_group_id            = aws_security_group.db.id
  description                  = "PostgreSQL from ${each.value}"
  referenced_security_group_id = each.value
  from_port                    = 5432
  to_port                      = 5432
  ip_protocol                  = "tcp"
}

# No egress rules: an RDS instance does not initiate outbound connections.

# ---------------------------------------------------------------------------
# Parameter group — enforce TLS
# ---------------------------------------------------------------------------

resource "aws_db_parameter_group" "main" {
  name_prefix = "${local.name}-pg"
  family      = "postgres${split(".", var.db_engine_version)[0]}"
  description = "Custom parameters for ${local.name}"

  parameter {
    name  = "rds.force_ssl"
    value = "1"
  }

  parameter {
    name         = "log_min_duration_statement"
    value        = "1000"
    apply_method = "immediate"
  }

  tags = local.common_tags

  lifecycle {
    create_before_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Enhanced monitoring role (prod)
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "rds_monitoring_assume" {
  count = local.is_prod ? 1 : 0

  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["monitoring.rds.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "rds_monitoring" {
  count = local.is_prod ? 1 : 0

  name               = "${local.name}-rds-monitoring"
  assume_role_policy = data.aws_iam_policy_document.rds_monitoring_assume[0].json
  tags               = local.common_tags
}

resource "aws_iam_role_policy_attachment" "rds_monitoring" {
  count = local.is_prod ? 1 : 0

  role       = aws_iam_role.rds_monitoring[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

# ---------------------------------------------------------------------------
# Instance
# ---------------------------------------------------------------------------

resource "aws_db_instance" "main" {
  identifier = "${local.name}-postgres"

  engine         = "postgres"
  engine_version = var.db_engine_version
  instance_class = var.db_instance_class

  db_name  = var.db_name
  username = var.db_username
  password = local.db_password_effective
  port     = 5432

  # --- Storage ---------------------------------------------------------
  allocated_storage     = var.db_allocated_storage
  max_allocated_storage = var.db_max_allocated_storage > 0 ? var.db_max_allocated_storage : null
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = local.data_kms_key_arn

  # --- Networking: private only ---------------------------------------
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]
  publicly_accessible    = false
  multi_az               = var.db_multi_az
  ca_cert_identifier     = "rds-ca-rsa2048-g1"

  parameter_group_name = aws_db_parameter_group.main.name

  # --- Backup / recovery ----------------------------------------------
  backup_retention_period   = var.db_backup_retention_days
  backup_window             = var.db_backup_window
  maintenance_window        = var.db_maintenance_window
  copy_tags_to_snapshot     = true
  delete_automated_backups  = !local.is_prod
  skip_final_snapshot       = !local.is_prod
  final_snapshot_identifier = local.is_prod ? "${local.name}-postgres-final-${formatdate("YYYYMMDDhhmmss", timestamp())}" : null

  # --- Safety ----------------------------------------------------------
  deletion_protection = true # spec: on in both environments

  # --- Upgrades --------------------------------------------------------
  auto_minor_version_upgrade  = true
  allow_major_version_upgrade = false
  apply_immediately           = var.db_apply_immediately

  # --- Observability ---------------------------------------------------
  enabled_cloudwatch_logs_exports       = ["postgresql", "upgrade"]
  performance_insights_enabled          = var.db_performance_insights_enabled
  performance_insights_retention_period = var.db_performance_insights_enabled ? (local.is_prod ? 731 : 7) : null
  performance_insights_kms_key_id       = var.db_performance_insights_enabled ? local.data_kms_key_arn : null
  monitoring_interval                   = local.is_prod ? 60 : 0
  monitoring_role_arn                   = local.is_prod ? aws_iam_role.rds_monitoring[0].arn : null

  # Allow DB auth tokens as an alternative to the master password.
  iam_database_authentication_enabled = true

  tags = merge(local.common_tags, { Name = "${local.name}-postgres" })

  lifecycle {
    # The final snapshot name embeds a timestamp; ignore it so it does not
    # cause perpetual diffs. Password drift is managed via Secrets Manager.
    ignore_changes = [final_snapshot_identifier]
  }
}
