## `modules/app-platform/secrets.tf`

```hcl
# ---------------------------------------------------------------------------
# The DB connection string lives only in Secrets Manager (encrypted at rest).
# It is never written to Git; the plaintext password enters Terraform either
# from a SOPS-decrypted tfvars file or is generated in-memory here.
# ---------------------------------------------------------------------------

resource "aws_secretsmanager_secret" "db" {
  name                    = "${local.name}/database/connection"
  description             = "PostgreSQL connection details for ${local.name}"
  kms_key_id              = local.data_kms_key_arn
  recovery_window_in_days = local.is_prod ? 30 : 0

  tags = merge(local.common_tags, { Name = "${local.name}-db-connection" })
}

resource "aws_secretsmanager_secret_version" "db" {
  secret_id = aws_secretsmanager_secret.db.id

  secret_string = jsonencode({
    engine   = "postgres"
    host     = aws_db_instance.main.address
    port     = aws_db_instance.main.port
    dbname   = aws_db_instance.main.db_name
    username = var.db_username
    password = local.db_password_effective

    # libpq URL, sslmode=require because rds.force_ssl=1
    url = format(
      "postgresql://%s:%s@%s:%d/%s?sslmode=require",
      var.db_username,
      urlencode(local.db_password_effective),
      aws_db_instance.main.address,
      aws_db_instance.main.port,
      aws_db_instance.main.db_name,
    )
  })

  lifecycle {
    # Rotation (Lambda or manual) may advance the version; do not fight it.
    ignore_changes = [secret_string]
  }
}
