## `modules/app-platform/iam.tf`

```hcl
# ---------------------------------------------------------------------------
# Service account role
#   prod: OIDC / IRSA web-identity trust, scoped to namespace:serviceaccount
#   dev : same, plus an optional IAM user for laptop workflows
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "app_assume" {
  # --- IRSA -----------------------------------------------------------
  dynamic "statement" {
    for_each = var.oidc_provider_arn != null ? [1] : []

    content {
      sid     = "AllowIRSAWebIdentity"
      effect  = "Allow"
      actions = ["sts:AssumeRoleWithWebIdentity"]

      principals {
        type        = "Federated"
        identifiers = [var.oidc_provider_arn]
      }

      condition {
        test     = "StringEquals"
        variable = "${local.oidc_issuer_host}:sub"
        values   = ["system:serviceaccount:${var.service_account_namespace}:${var.service_account_name}"]
      }

      condition {
        test     = "StringEquals"
        variable = "${local.oidc_issuer_host}:aud"
        values   = ["sts.amazonaws.com"]
      }
    }
  }

  # --- dev-only: allow the programmatic user to assume the role -------
  dynamic "statement" {
    for_each = var.create_iam_user ? [1] : []

    content {
      sid     = "AllowDevUserAssume"
      effect  = "Allow"
      actions = ["sts:AssumeRole"]

      principals {
        type        = "AWS"
        identifiers = [aws_iam_user.app[0].arn]
      }
    }
  }
}

locals {
  # arn:aws:iam::123:oidc-provider/oidc.eks.eu-west-1.amazonaws.com/id/ABC
  #   -> oidc.eks.eu-west-1.amazonaws.com/id/ABC
  oidc_issuer_host = var.oidc_provider_arn != null ? replace(
    var.oidc_provider_arn,
    "/^arn:[^:]*:iam::[0-9]{12}:oidc-provider//",
    ""
  ) : ""
}

resource "aws_iam_role" "app" {
  name                 = "${local.name}-app"
  description          = "Application service account role for ${local.name}"
  assume_role_policy   = data.aws_iam_policy_document.app_assume.json
  max_session_duration = 3600
  force_detach_policies = true

  tags = merge(local.common_tags, { Name = "${local.name}-app" })
}

# ---------------------------------------------------------------------------
# Least-privilege policy: explicit actions, prefix-scoped resources.
# No wildcard actions anywhere. No "*" resources except where the API
# mandates it (none here).
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "app" {
  statement {
    sid    = "ListBucketScopedToPrefixes"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]

    resources = [aws_s3_bucket.assets.arn]

    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values   = local.allowed_list_prefixes
    }
  }

  statement {
    sid    = "ReadWriteObjectPrefixes"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:AbortMultipartUpload",
      "s3:ListMultipartUploadParts",
    ]

    resources = local.rw_object_arns
  }

  dynamic "statement" {
    for_each = length(local.ro_object_arns) > 0 ? [1] : []

    content {
      sid    = "ReadOnlyObjectPrefixes"
      effect = "Allow"

      actions = [
        "s3:GetObject",
        "s3:GetObjectVersion",
      ]

      resources = local.ro_object_arns
    }
  }

  statement {
    sid    = "ReadDatabaseSecret"
    effect = "Allow"

    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:DescribeSecret",
    ]

    resources = [aws_secretsmanager_secret.db.arn]
  }

  statement {
    sid    = "ConnectViaIAMAuth"
    effect = "Allow"

    actions = ["rds-db:connect"]

    resources = [
      format(
        "arn:%s:rds-db:%s:%s:dbuser:%s/%s",
        data.aws_partition.current.partition,
        data.aws_region.current.name,
        data.aws_caller_identity.current.account_id,
        aws_db_instance.main.resource_id,
        var.db_username,
      )
    ]
  }

  # CMK access is required to decrypt the secret in prod.
  dynamic "statement" {
    for_each = local.data_kms_key_arn != null ? [1] : []

    content {
      sid    = "DecryptWithDataKey"
      effect = "Allow"

      actions = [
        "kms:Decrypt",
        "kms:DescribeKey",
      ]

      resources = [local.data_kms_key_arn]

      condition {
        test     = "StringEquals"
        variable = "kms:ViaService"
        values = [
          "secretsmanager.${data.aws_region.current.name}.amazonaws.com",
          "s3.${data.aws_region.current.name}.amazonaws.com",
        ]
      }
    }
  }
}

resource "aws_iam_policy" "app" {
  name        = "${local.name}-app"
  description = "Least-privilege access to ${local.name} assets bucket and DB secret"
  policy      = data.aws_iam_policy_document.app.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "app" {
  role       = aws_iam_role.app.name
  policy_arn = aws_iam_policy.app.arn
}

# ---------------------------------------------------------------------------
# dev-only programmatic user. Its ONLY permission is sts:AssumeRole onto the
# app role, so the blast radius equals the role's own policy.
# ---------------------------------------------------------------------------

resource "aws_iam_user" "app" {
  count = var.create_iam_user ? 1 : 0

  name = "${local.name}-app"
  path = "/service/"

  tags = merge(local.common_tags, { Name = "${local.name}-app" })
}

data "aws_iam_policy_document" "app_user" {
  count = var.create_iam_user ? 1 : 0

  statement {
    sid       = "AssumeAppRoleOnly"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.app.arn]
  }
}

resource "aws_iam_user_policy" "app" {
  count = var.create_iam_user ? 1 : 0

  name   = "assume-app-role"
  user   = aws_iam_user.app[0].name
  policy = data.aws_iam_policy_document.app_user[0].json
}

resource "aws_iam_access_key" "app" {
  count = var.create_iam_user ? 1 : 0

  user = aws_iam_user.app[0].name
}

# Keys are stored in Secrets Manager, never emitted as a root output in cleartext.
resource "aws_secretsmanager_secret" "app_user_keys" {
  count = var.create_iam_user ? 1 : 0

  name                    = "${local.name}/iam/app-user-access-key"
  description             = "Programmatic credentials for ${local.name} dev workflows"
  recovery_window_in_days = 0

  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "app_user_keys" {
  count = var.create_iam_user ? 1 : 0

  secret_id = aws_secretsmanager_secret.app_user_keys[0].id

  secret_string = jsonencode({
    access_key_id     = aws_iam_access_key.app[0].id
    secret_access_key = aws_iam_access_key.app[0].secret
    assume_role_arn   = aws_iam_role.app.arn
  })
}
